/**
 * @description Data-free tests (no DML, no records, no callouts) for inbound and callback validation, status mapping
 * and the answers sent back.
 */
@IsTest
private class IntegrationHubUnitTestInbound {

    private static User me() {
        return new User(Id = UserInfo.getUserId());
    }

    private static Id fakeTransactionId() {
        return Id.valueOf(IH_Transaction__c.SObjectType.getDescribe(SObjectDescribeOptions.DEFERRED).getKeyPrefix() + '000000000001');
    }

    private static RestResponse rest(String path, String body) {
        RestRequest req = new RestRequest();
        req.requestURI = '/services/apexrest/integrationhub/v1/' + path;
        req.requestBody = body == null ? null : Blob.valueOf(body);
        RestContext.request = req;
        RestContext.response = new RestResponse();
        return RestContext.response;
    }

    @IsTest
    static void callbackStatusMapping() {
        System.runAs(me()) {
            for (String word : new List<String>{ 'SUCCESS', 'ACCEPTED', 'ok', ' Created ', 'completed' }) {
                Assert.areEqual(IntegrationHub.STATUS_SUCCESS, IntegrationHubCallback.mapStatus(word), word + ' means Success');
            }
            for (String word : new List<String>{ 'FAILED', 'rejected', ' Error' }) {
                Assert.areEqual(IntegrationHub.STATUS_FAILED, IntegrationHubCallback.mapStatus(word), word + ' means Failed');
            }
            for (String word : new List<String>{ null, '', 'PENDING', 'IN_PROGRESS' }) {
                Assert.isNull(IntegrationHubCallback.mapStatus(word), word + ' leaves the status unchanged');
            }
        }
    }

    @IsTest
    static void callbackValidation() {
        System.runAs(me()) {
            Assert.isNull(IntegrationHubCallback.toTransactionId(null), 'no Id');
            Assert.isNull(IntegrationHubCallback.toTransactionId('abc'), 'not an Id');
            Assert.isNull(IntegrationHubCallback.toTransactionId(UserInfo.getUserId()), 'an Id of another object');
            Assert.areEqual(fakeTransactionId(), IntegrationHubCallback.toTransactionId(' ' + fakeTransactionId() + ' '), 'a transaction Id');
            Assert.areEqual(404, IntegrationHubCallback.callbackProblem(null, '{}'), 'no transaction is 404');
            Assert.areEqual(409, IntegrationHubCallback.callbackProblem(IntegrationHub.INBOUND, '{}'), 'inbound is 409');
            Assert.areEqual(400, IntegrationHubCallback.callbackProblem(IntegrationHub.OUTBOUND, ''), 'empty body is 400');
            Assert.areEqual(400, IntegrationHubCallback.callbackProblem(IntegrationHub.OUTBOUND, 'not json'), 'invalid JSON is 400');
            Assert.areEqual(400, IntegrationHubCallback.callbackProblem(IntegrationHub.OUTBOUND, '[1]'), 'an array is 400');
            Assert.isNull(IntegrationHubCallback.callbackProblem(IntegrationHub.OUTBOUND, '{"status":"OK"}'), 'a valid callback');
            Assert.isNull(IntegrationHubCallback.callbackProblem('', '{}'), 'a blank direction is not inbound');
            Assert.areEqual('Transaction not found: x', IntegrationHubCallback.problemMessage(404, 'x'), '404 text');
            Assert.areEqual('Callbacks are only for outbound transactions.', IntegrationHubCallback.problemMessage(409, 'x'), '409 text');
            Assert.areEqual('The body must be a JSON object.', IntegrationHubCallback.problemMessage(400, 'x'), '400 text');
        }
    }

    @IsTest
    static void inboundRequestHelpers() {
        System.runAs(me()) {
            Assert.isNull(IntegrationHubInbound.requestKey('EV', ' '), 'no request Id, no key');
            Assert.areEqual('EV:r-1', IntegrationHubInbound.requestKey('EV', 'r-1'), 'event key and request Id');
            Assert.areEqual(255, IntegrationHubInbound.requestKey('EV', 'x'.repeat(300)).length(), 'the key is clipped');
            Map<String, String> headers = new Map<String, String>{ 'x-request-id' => 'abc' };
            Assert.areEqual('abc', IntegrationHubInbound.header(headers, 'X-Request-Id'), 'headers match without case');
            Assert.isNull(IntegrationHubInbound.header(null, 'X-Request-Id'), 'no headers');
            Assert.isNull(IntegrationHubInbound.parseObject(''), 'empty body');
            Assert.isNull(IntegrationHubInbound.parseObject('[1]'), 'an array is not an object');
            Assert.isNull(IntegrationHubInbound.parseObject('{oops'), 'invalid JSON');
            Assert.areEqual(1, IntegrationHubInbound.parseObject('{"a":1}').get('a'), 'an object');
            IntegrationHubInbound.Request req = new IntegrationHubInbound.Request();
            req.eventKey = 'NOPE';
            IntegrationHubInbound.Response r = IntegrationHubInbound.refusal(req, null, null);
            Assert.areEqual(404, r.statusCode, 'an unknown event is refused before any query');
            Assert.areEqual(IntegrationHub.STATUS_FAILED, r.body.get('status'), 'error bodies say Failed');
        }
    }

    @IsTest
    static void inboundResultToAnswer() {
        System.runAs(me()) {
            Id txnId = fakeTransactionId();
            IH_Transaction__c ok = new IH_Transaction__c(Id = txnId);
            IntegrationHubInbound.Response r = IntegrationHubInbound.finish(ok,
                IntegrationHub.inboundSuccess(UserInfo.getUserId(), new Map<String, Object>{ 'n' => 1 }));
            Assert.areEqual(200, r.statusCode, 'success is 200');
            Assert.areEqual(UserInfo.getUserId(), r.body.get('recordId'), 'the record is returned');
            Assert.areEqual(txnId, r.body.get('transactionId'), 'the transaction is returned');
            Assert.areEqual('User', ok.Related_Object__c, 'the record type is stored');
            Assert.areEqual(IntegrationHub.STATUS_SUCCESS, ok.Status__c, 'the transaction succeeded');
            IH_Transaction__c failed = new IH_Transaction__c(Id = txnId);
            r = IntegrationHubInbound.finish(failed, IntegrationHub.inboundFailure(400, 'Missing name'));
            Assert.areEqual(400, r.statusCode, 'the handler code is used');
            Assert.areEqual('Missing name', r.body.get('error'), 'the handler message is returned');
            Assert.areEqual(IntegrationHub.STATUS_FAILED, failed.Status__c, 'the transaction failed');
            IntegrationHub.InboundResult noCode = new IntegrationHub.InboundResult();
            Assert.areEqual(422, IntegrationHubInbound.finish(new IH_Transaction__c(), noCode).statusCode, 'no code is 422');
            r = IntegrationHubInbound.finish(new IH_Transaction__c(), null);
            Assert.areEqual(422, r.statusCode, 'no result is 422');
            Assert.areEqual('The handler returned no result.', r.body.get('error'), 'no result is explained');
        }
    }

    @IsTest
    static void replayUsesStoredAnswer() {
        System.runAs(me()) {
            IntegrationHubInbound.Response r = IntegrationHubInbound.replay(
                new IH_Transaction__c(Http_Status_Code__c = 400, Response_Body__c = '{"error":"x"}'));
            Assert.areEqual(400, r.statusCode, 'the stored code');
            Assert.areEqual('x', r.body.get('error'), 'the stored body');
            Assert.isTrue(r.replay, 'marked as a replay');
            r = IntegrationHubInbound.replay(new IH_Transaction__c(Status__c = 'Received'));
            Assert.areEqual(200, r.statusCode, 'no stored code is 200');
            Assert.areEqual('Received', r.body.get('status'), 'no stored body gives the status');
        }
    }

    @IsTest
    static void unknownPathsAnswer404() {
        System.runAs(me()) {
            RestResponse res = rest('other/abc', '{}');
            IntegrationHubInboundApi.callback();
            Assert.areEqual(404, res.statusCode, 'PATCH needs callback/');
            res = rest('other', null);
            IntegrationHubInboundApi.status();
            Assert.areEqual(405, res.statusCode, 'GET on an event path answers 405');
            res = rest('', '{}');
            IntegrationHubInboundApi.receive();
            Assert.areEqual(404, res.statusCode, 'POST needs an event key');
            Assert.areEqual('application/json', res.headers.get('Content-Type'), 'answers are JSON');
        }
    }
}
